1: /**
2:  * BNJI.NET — message board storage providers.
3:  *
4:  * The API route (src/pages/api/board.ts) talks only to this module; the UI
5:  * talks only to the API. That is the whole boundary: swapping persistence
6:  * never touches a component.
7:  *
8:  * Providers
9:  * ---------
10:  *  memory — module-scope array. Lives as long as the Worker isolate does, so
11:  *           messages are shared by visitors served by the same isolate and
12:  *           survive between requests, but not across isolates/deployments.
13:  *           Zero configuration; this is the default and the honest demo grade.
14:  *  kv     — Cloudflare KV, true persistence. Auto-detected: if the Worker
15:  *           environment exposes a BOARD_KV namespace binding, this provider is
16:  *           used automatically. Enable it with:
17:  *             npx wrangler kv namespace create board
18:  *           then add a binding named BOARD_KV in wrangler.json
19:  *           (see docs/CONFIGURATION.md). No code changes needed.
20:  *  rest   — external JSON API (GET/POST {messages}) for teams that already
21:  *           run a backend. Configured via BOARD_REST_URL / BOARD_REST_TOKEN
22:  *           environment variables (secret; never in this file).
23:  *
24:  * Data model (deliberately tiny and serialisable):
25:  *   { id, text, image?, hue, createdAt }
26:  * `image` is stored ONLY as a validated data: URL of an allowed MIME type and
27:  * size (validated again server-side on write). `hue` is a stable 0-359 tint
28:  * seed so each bubble/star gets its own colour without storing one.
29:  */
30: import { BOARD_CONFIG } from '../config/board.config';
31: 
32: export type BoardMessage = {
33: 	id: string;
34: 	text: string;
35: 	/** Validated data: URL, or undefined. Never an arbitrary remote URL. */
36: 	image?: string;
37: 	/** Stable tint seed 0-359. */
38: 	hue: number;
39: 	/** Epoch ms. */
40: 	createdAt: number;
41: };
42: 
43: export interface BoardStore {
44: 	/** Newest first. `limit` caps the result; `all` bypasses the default cap. */
45: 	list(limit: number): Promise<BoardMessage[]>;
46: 	add(message: BoardMessage): Promise<void>;
47: 	readonly kind: 'memory' | 'kv' | 'rest';
48: }
49: 
50: /* --- memory provider ------------------------------------------------------ */
51: 
52: const memory: BoardMessage[] = [];
53: 
54: const memoryStore: BoardStore = {
55: 	kind: 'memory',
56: 	async list(limit) {
57: 		return memory
58: 			.slice()
59: 			.sort((a, b) => b.createdAt - a.createdAt)
60: 			.slice(0, limit);
61: 	},
62: 	async add(message) {
63: 		memory.push(message);
64: 		// Hard cap so a long-lived isolate cannot grow without bound.
65: 		if (memory.length > 500) memory.splice(0, memory.length - 500);
66: 	},
67: };
68: 
69: /* --- kv provider ----------------------------------------------------------- */
70: 
71: type KvNamespace = {
72: 	get(key: string): Promise<string | null>;
73: 	put(key: string, value: string): Promise<void>;
74: };
75: 
76: function createKvStore(kv: KvNamespace): BoardStore {
77: 	const INDEX = 'board:index';
78: 	return {
79: 		kind: 'kv',
80: 		async list(limit) {
81: 			const rawIndex = await kv.get(INDEX);
82: 			const ids: string[] = rawIndex ? (JSON.parse(rawIndex) as string[]) : [];
83: 			const messages: BoardMessage[] = [];
84: 			for (const id of ids.slice(0, limit)) {
85: 				const raw = await kv.get(`board:msg:${id}`);
86: 				if (raw) messages.push(JSON.parse(raw) as BoardMessage);
87: 			}
88: 			return messages;
89: 		},
90: 		async add(message) {
91: 			await kv.put(`board:msg:${message.id}`, JSON.stringify(message));
92: 			const rawIndex = await kv.get(INDEX);
93: 			const ids: string[] = rawIndex ? (JSON.parse(rawIndex) as string[]) : [];
94: 			ids.unshift(message.id);
95: 			await kv.put(INDEX, JSON.stringify(ids.slice(0, 500)));
96: 		},
97: 	};
98: }
99: 
100: /* --- rest provider ---------------------------------------------------------- */
101: 
102: function createRestStore(url: string, token?: string): BoardStore {
103: 	const headers = (): Record<string, string> => ({
104: 		'content-type': 'application/json',
105: 		...(token ? { authorization: `Bearer ${token}` } : {}),
106: 	});
107: 	return {
108: 		kind: 'rest',
109: 		async list(limit) {
110: 			const response = await fetch(`${url}?limit=${limit}`, { headers: headers() });
111: 			if (!response.ok) throw new Error(`board rest list failed: ${response.status}`);
112: 			const data = (await response.json()) as { messages: BoardMessage[] };
113: 			return data.messages;
114: 		},
115: 		async add(message) {
116: 			const response = await fetch(url, {
117: 				method: 'POST',
118: 				headers: headers(),
119: 				body: JSON.stringify(message),
120: 			});
121: 			if (!response.ok) throw new Error(`board rest add failed: ${response.status}`);
122: 		},
123: 	};
124: }
125: 
126: /* --- selection -------------------------------------------------------------- */
127: 
128: /**
129:  * Resolve the active store for one request. `env` is the Worker environment
130:  * (Astro.locals.runtime.env); bindings and secrets arrive there and nowhere
131:  * else. Falls back to memory when the configured provider is unavailable, so
132:  * the board UI always works.
133:  */
134: export function getBoardStore(env: Record<string, unknown> | undefined): BoardStore {
135: 	const configured = BOARD_CONFIG.provider;
136: 	if (configured === 'kv' || configured === 'memory') {
137: 		const kv = env?.BOARD_KV as KvNamespace | undefined;
138: 		if (kv && typeof kv.get === 'function') return createKvStore(kv);
139: 	}
140: 	if (configured === 'rest') {
141: 		const url = env?.BOARD_REST_URL as string | undefined;
142: 		if (url) return createRestStore(url, env?.BOARD_REST_TOKEN as string | undefined);
143: 	}
144: 	return memoryStore;
145: }

