1: /**
2:  * BNJI.NET — public message board API boundary.
3:  *
4:  *   GET  /api/board?limit=N   newest-first messages, N clamped to pageSize
5:  *        /api/board?all=1     up to 200 messages (the "full list" view)
6:  *   POST /api/board           { text, image? } -> 201 { message }
7:  *
8:  * This endpoint is NOT prerendered: it runs in the Worker on every request so
9:  * it can read environment bindings (storage) and enforce rate limits.
10:  *
11:  * Safety contract for user-generated content:
12:  *   - text: trimmed, control characters stripped, hard length cap;
13:  *     rendered client-side via textContent only (never innerHTML);
14:  *   - image: accepted ONLY as a data: URL of an allowed MIME type under the
15:  *     size cap; re-validated here (never trust the client); stored as-is and
16:  *     rendered in an <img> with no scripting surface;
17:  *   - rate limit: one post per cooldown per client address, plus an hourly cap;
18:  *   - no credentials ever flow to the client; storage secrets live in env.
19:  */
20: import { BOARD_CONFIG } from '../../config/board.config';
21: import { getBoardStore, type BoardMessage } from '../../server/board-store';
22: import { rateLimit, retryAfterSeconds } from '../../server/ratelimit';
23: import { serverEnvironment } from '../../server/env';
24: import type { APIContext } from 'astro';
25: 
26: export const prerender = false;
27: 
28: const CONTROL_CHARS = /[\u0000-\u0008\u000b-\u001f\u007f]/g;
29: 
30: function clientKey(request: Request): string {
31: 	const cf = (request as Request & { cf?: { connectingIp?: string } }).cf;
32: 	return cf?.connectingIp ?? request.headers.get('cf-connecting-ip') ?? 'unknown';
33: }
34: 
35: function json(data: unknown, status = 200): Response {
36: 	return new Response(JSON.stringify(data), {
37: 		status,
38: 		headers: {
39: 			'content-type': 'application/json',
40: 			// Board data is never cached by the edge: visitors must see fresh
41: 			// messages, and POST responses must not be replayed.
42: 			'cache-control': 'no-store',
43: 		},
44: 	});
45: }
46: 
47: /** Re-validate an attached image data URL. Returns the URL or undefined. */
48: function sanitizeImage(value: unknown): string | undefined {
49: 	if (typeof value !== 'string' || value.length === 0) return undefined;
50: 	const match = /^data:(image\/(?:png|jpeg|webp|gif));base64,([A-Za-z0-9+/=]+)$/.exec(value);
51: 	if (!match) return undefined;
52: 	if (!BOARD_CONFIG.allowedImageTypes.includes(match[1])) return undefined;
53: 	// base64 length -> bytes (3/4 ratio), must fit the configured cap.
54: 	const bytes = Math.floor((match[2].length * 3) / 4);
55: 	if (bytes > BOARD_CONFIG.maxImageBytes) return undefined;
56: 	return value;
57: }
58: 
59: export async function GET(context: APIContext): Promise<Response> {
60: 	const env = await serverEnvironment();
61: 	const store = getBoardStore(env);
62: 
63: 	const wantsAll = context.url.searchParams.get('all') === '1';
64: 	const requested = Number(context.url.searchParams.get('limit') ?? BOARD_CONFIG.defaultVisible);
65: 	const limit = wantsAll
66: 		? 200
67: 		: Math.min(Math.max(1, Number.isFinite(requested) ? requested : BOARD_CONFIG.defaultVisible), BOARD_CONFIG.pageSize);
68: 
69: 	try {
70: 		const messages = await store.list(limit);
71: 		return json({ messages, provider: store.kind, limit });
72: 	} catch (error) {
73: 		console.error('[bnji] board list failed:', error);
74: 		return json({ error: 'storage_unavailable', messages: [] }, 503);
75: 	}
76: }
77: 
78: export async function POST(context: APIContext): Promise<Response> {
79: 	const env = await serverEnvironment();
80: 	const store = getBoardStore(env);
81: 	const key = clientKey(context.request);
82: 
83: 	// Abuse protection: cooldown + hourly cap, per client address.
84: 	if (!rateLimit(`board:post:${key}`, BOARD_CONFIG.postCooldownSeconds * 1000, 1)) {
85: 		return json(
86: 			{
87: 				error: 'rate_limited',
88: 				retryAfter: retryAfterSeconds(`board:post:${key}`, BOARD_CONFIG.postCooldownSeconds * 1000),
89: 			},
90: 			429,
91: 		);
92: 	}
93: 	if (!rateLimit(`board:hour:${key}`, 3_600_000, 20)) {
94: 		return json({ error: 'rate_limited', retryAfter: 60 }, 429);
95: 	}
96: 
97: 	let payload: unknown;
98: 	try {
99: 		payload = await context.request.json();
100: 	} catch {
101: 		return json({ error: 'invalid_json' }, 400);
102: 	}
103: 	const body = (payload ?? {}) as { text?: unknown; image?: unknown };
104: 
105: 	const text = typeof body.text === 'string' ? body.text.replace(CONTROL_CHARS, '').trim() : '';
106: 	if (text.length === 0) return json({ error: 'empty_text' }, 422);
107: 	if (text.length > BOARD_CONFIG.maxTextLength) {
108: 		return json({ error: 'text_too_long', maxLength: BOARD_CONFIG.maxTextLength }, 422);
109: 	}
110: 	const image = sanitizeImage(body.image);
111: 
112: 	const message: BoardMessage = {
113: 		id: `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
114: 		text,
115: 		...(image ? { image } : {}),
116: 		// Stable tint seed, derived once so every visitor sees the same hue.
117: 		hue: Math.floor(Math.random() * 360),
118: 		createdAt: Date.now(),
119: 	};
120: 
121: 	try {
122: 		await store.add(message);
123: 		return json({ message, provider: store.kind }, 201);
124: 	} catch (error) {
125: 		console.error('[bnji] board add failed:', error);
126: 		return json({ error: 'storage_unavailable' }, 503);
127: 	}
128: }

