1: /**
2:  * BNJI.NET — tiny in-isolate rate limiter.
3:  *
4:  * A sliding-window counter per client key (IP). Lives in module scope, so it
5:  * is per-Worker-isolate: good enough to stop casual abuse and runaway loops,
6:  * and honest about being so. For strict global limits, put a Cloudflare
7:  * rate-limiting rule in front of /api/* — that is an edge configuration, not
8:  * application code.
9:  *
10:  * No secrets, no credentials: keys are hashed client addresses only, and the
11:  * map is capped and pruned so it cannot grow without bound.
12:  */
13: type Bucket = { stamps: number[] };
14: 
15: const buckets = new Map<string, Bucket>();
16: const MAX_KEYS = 2000;
17: 
18: /**
19:  * @param key      client identity (e.g. Astro.clientAddress)
20:  * @param windowMs sliding window size
21:  * @param maxHits  allowed hits inside the window
22:  * @returns true when the hit is allowed (and recorded)
23:  */
24: export function rateLimit(key: string, windowMs: number, maxHits: number): boolean {
25: 	const now = Date.now();
26: 	let bucket = buckets.get(key);
27: 	if (!bucket) {
28: 		if (buckets.size > MAX_KEYS) {
29: 			// Prune stale keys instead of unbounded growth.
30: 			for (const [k, b] of buckets) {
31: 				if (b.stamps.length === 0 || now - b.stamps[b.stamps.length - 1] > windowMs) {
32: 					buckets.delete(k);
33: 				}
34: 			}
35: 		}
36: 		bucket = { stamps: [] };
37: 		buckets.set(key, bucket);
38: 	}
39: 	bucket.stamps = bucket.stamps.filter((t) => now - t < windowMs);
40: 	if (bucket.stamps.length >= maxHits) return false;
41: 	bucket.stamps.push(now);
42: 	return true;
43: }
44: 
45: /** Seconds until the oldest stamp in the window expires (for Retry-After). */
46: export function retryAfterSeconds(key: string, windowMs: number): number {
47: 	const bucket = buckets.get(key);
48: 	if (!bucket || bucket.stamps.length === 0) return 0;
49: 	const oldest = bucket.stamps[0];
50: 	return Math.max(1, Math.ceil((windowMs - (Date.now() - oldest)) / 1000));
51: }

