1: /**
2:  * BNJI.NET — server-side access-control primitives.
3:  *
4:  * The honest model:
5:  *   - src/config/access.config.ts DECLARES which routes are protected and how.
6:  *   - src/middleware.ts ENFORCES those rules on every request that actually
7:  *     runs Worker code (i.e. non-prerendered routes).
8:  *   - Prerendered static pages CANNOT be protected (the edge serves them
9:  *     without running code). A route that must be private sets
10:  *     `export const prerender = false;` in its page file.
11:  *   - Client-side hiding is never used as protection, anywhere.
12:  *
13:  * Credentials (environment only — never in the repo):
14:  *   ACCESS_TOKEN          shared bearer token for auth: 'token' rules
15:  *   ACCESS_PASSWORD_SHA   sha256(hex) of the password for auth: 'password'
16:  *   ACCESS_SECRET         HMAC key signing the session cookie
17:  *
18:  * With an empty ACCESS_RULES list (the default) every current page remains
19:  * public and this module is a no-op. Nothing here fakes security: checks are
20:  * constant-time, sessions are signed, and failures log without leaking why.
21:  */
22: import type { RouteAccessRule } from '../config/access.config';
23: 
24: type AccessContext = {
25: 	request: Request;
26: 	cookies: { get(name: string): { value: string } | undefined };
27: };
28: 
29: const SESSION_COOKIE = 'bnji_session';
30: 
31: async function sha256Hex(value: string): Promise<string> {
32: 	const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));
33: 	return Array.from(new Uint8Array(digest))
34: 		.map((b) => b.toString(16).padStart(2, '0'))
35: 		.join('');
36: }
37: 
38: async function hmacHex(secret: string, value: string): Promise<string> {
39: 	const key = await crypto.subtle.importKey(
40: 		'raw',
41: 		new TextEncoder().encode(secret),
42: 		{ name: 'HMAC', hash: 'SHA-256' },
43: 		false,
44: 		['sign'],
45: 	);
46: 	const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(value));
47: 	return Array.from(new Uint8Array(sig))
48: 		.map((b) => b.toString(16).padStart(2, '0'))
49: 		.join('');
50: }
51: 
52: function timingSafeEqual(a: string, b: string): boolean {
53: 	if (a.length !== b.length) return false;
54: 	let diff = 0;
55: 	for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
56: 	return diff === 0;
57: }
58: 
59: /** True when the request carries a valid session signature for the rule. */
60: async function hasValidSession(ctx: AccessContext, secret: string): Promise<boolean> {
61: 	const cookie = ctx.cookies.get(SESSION_COOKIE)?.value;
62: 	if (!cookie) return false;
63: 	const [payload, signature] = cookie.split('.');
64: 	if (!payload || !signature) return false;
65: 	const expected = await hmacHex(secret, payload);
66: 	if (!timingSafeEqual(expected, signature)) return false;
67: 	// payload = "<rulePattern>:<expiryEpochSeconds>"
68: 	const [pattern, expiry] = payload.split(':');
69: 	const expires = Number(expiry);
70: 	if (!Number.isFinite(expires) || expires < Date.now() / 1000) return false;
71: 	return pattern !== undefined;
72: }
73: 
74: /**
75:  * Verify a presented credential against the rule. Used by (future) login
76:  * endpoints; the middleware itself only checks bearer tokens and sessions.
77:  */
78: export async function verifyCredential(
79: 	rule: RouteAccessRule,
80: 	credential: string,
81: 	env: Record<string, string | undefined>,
82: ): Promise<boolean> {
83: 	if (rule.auth === 'token') {
84: 		const expected = env.ACCESS_TOKEN;
85: 		return expected ? timingSafeEqual(credential, expected) : false;
86: 	}
87: 	const expectedSha = env.ACCESS_PASSWORD_SHA;
88: 	if (!expectedSha) return false;
89: 	const presented = await sha256Hex(credential);
90: 	return timingSafeEqual(presented, expectedSha);
91: }
92: 
93: /** Issue a signed session cookie value for a rule (8h expiry). */
94: export async function issueSession(
95: 	rule: RouteAccessRule,
96: 	env: Record<string, string | undefined>,
97: ): Promise<string | null> {
98: 	const secret = env.ACCESS_SECRET;
99: 	if (!secret) return null;
100: 	const payload = `${rule.pattern}:${Math.floor(Date.now() / 1000) + 8 * 3600}`;
101: 	const signature = await hmacHex(secret, payload);
102: 	return `${payload}.${signature}`;
103: }
104: 
105: export const SESSION_COOKIE_NAME = SESSION_COOKIE;
106: 
107: /** Middleware entry: is this request authorized for the matched rule? */
108: export async function isAuthorized(
109: 	ctx: AccessContext,
110: 	rule: RouteAccessRule,
111: 	env: Record<string, string | undefined>,
112: ): Promise<boolean> {
113: 	// No credentials configured => the rule cannot pass. Failing closed is
114: 	// the only honest behaviour: an unconfigured guard must not open the door.
115: 	if (!env.ACCESS_SECRET && !env.ACCESS_TOKEN && !env.ACCESS_PASSWORD_SHA) return false;
116: 
117: 	if (env.ACCESS_SECRET && (await hasValidSession(ctx, env.ACCESS_SECRET))) return true;
118: 
119: 	if (rule.auth === 'token' && env.ACCESS_TOKEN) {
120: 		const header = ctx.request.headers.get('authorization') ?? '';
121: 		const bearer = header.startsWith('Bearer ') ? header.slice(7) : '';
122: 		return timingSafeEqual(bearer, env.ACCESS_TOKEN);
123: 	}
124: 	return false;
125: }

