/**
 * BNJI.NET — message board storage providers.
 *
 * The API route (src/pages/api/board.ts) talks only to this module; the UI
 * talks only to the API. That is the whole boundary: swapping persistence
 * never touches a component.
 *
 * Providers
 * ---------
 *  memory — module-scope array. Lives as long as the Worker isolate does, so
 *           messages are shared by visitors served by the same isolate and
 *           survive between requests, but not across isolates/deployments.
 *           Zero configuration; this is the default and the honest demo grade.
 *  d1     — Cloudflare D1 database, true persistence. Auto-detected: if the
 *           Worker environment exposes a BOARD_D1 database binding, this
 *           provider is used automatically. Enable it with:
 *             npx wrangler d1 create board
 *           then add a binding named BOARD_D1 in wrangler.json
 *           (see docs/CONFIGURATION.md). No code changes needed.
 *  kv     — Cloudflare KV, true persistence. Auto-detected: if the Worker
 *           environment exposes a BOARD_KV namespace binding, this provider is
 *           used automatically. Enable it with:
 *             npx wrangler kv namespace create board
 *           then add a binding named BOARD_KV in wrangler.json
 *           (see docs/CONFIGURATION.md). No code changes needed.
 *  rest   — external JSON API (GET/POST {messages}) for teams that already
 *           run a backend. Configured via BOARD_REST_URL / BOARD_REST_TOKEN
 *           environment variables (secret; never in this file).
 *
 * Data model (deliberately tiny and serialisable):
 *   { id, text, image?, hue, status, createdAt }
 * `image` is stored ONLY as a validated data: URL of an allowed MIME type and
 * size (validated again server-side on write). `hue` is a stable 0-359 tint
 * seed so each bubble/star gets its own colour without storing one.
 * `status` is a moderation field: 'visible' | 'hidden' | 'reported' | 'deleted'.
 * Non-visible messages never reach the public fetch endpoint.
 */
import { BOARD_CONFIG } from '../config/board.config';

export type MessageStatus = 'visible' | 'hidden' | 'reported' | 'deleted';

export type BoardMessage = {
	id: string;
	text: string;
	/** Validated data: URL, or undefined. Never an arbitrary remote URL. */
	image?: string;
	/** Stable tint seed 0-359. */
	hue: number;
	/** Moderation status. Hidden/deleted/reported never reach the public fetch. */
	status: MessageStatus;
	/** Epoch ms. */
	createdAt: number;
};

export type ListMessagesOptions = {
	/** Maximum number of messages to return. */
	limit: number;
	/** Cursor for pagination (opaque encoded cursor). */
	cursor?: string;
};

export type ListMessagesResult = {
	/** Messages, newest first, filtered to visible only. */
	messages: BoardMessage[];
	/** Opaque cursor for the next page, or undefined if no more. */
	nextCursor?: string;
};

export interface BoardStore {
	/** Newest first, visible-only. Supports cursor-based pagination. */
	listMessages(opts: ListMessagesOptions): Promise<ListMessagesResult>;
	/** Store a new message. */
	add(message: BoardMessage): Promise<void>;
	/** Update a message's status (for moderation operations). */
	updateStatus(id: string, status: MessageStatus): Promise<boolean>;
	readonly kind: 'memory' | 'd1' | 'kv' | 'rest';
}

/* --- memory provider ------------------------------------------------------ */

const memory: BoardMessage[] = [];

const memoryStore: BoardStore = {
	kind: 'memory',
	async listMessages({ limit, cursor }) {
		let items = memory
			.slice()
			.filter((m) => m.status === 'visible')
			.sort((a, b) => b.createdAt - a.createdAt);

		if (cursor) {
			const decoded = decodeCursor(cursor);
			if (decoded) {
				// Find the position of the cursor message and get items after it
				const cursorIdx = items.findIndex((m) => m.createdAt <= decoded);
				if (cursorIdx !== -1) {
					items = items.slice(cursorIdx);
				} else if (decoded < items[items.length - 1]?.createdAt) {
					// Cursor is older than the last available message; return empty
					items = [];
				}
			}
		}

		const messages = items.slice(0, limit);
		const nextCursor =
			messages.length === limit && messages.length > 0
				? encodeCursor(messages[messages.length - 1].createdAt)
				: undefined;

		return { messages, nextCursor };
	},
	async add(message) {
		memory.push(message);
		// Hard cap so a long-lived isolate cannot grow without bound.
		if (memory.length > 500) memory.splice(0, memory.length - 500);
	},
	async updateStatus(id, status) {
		const idx = memory.findIndex((m) => m.id === id);
		if (idx === -1) return false;
		memory[idx].status = status;
		return true;
	},
};

/* --- d1 provider ----------------------------------------------------------- */

type D1Database = {
	prepare(query: string): {
		bind(...values: unknown[]): { all: () => Promise<unknown[]>; run: () => Promise<{ success: boolean }>; first: () => Promise<unknown | null>; };
	};
};

/** Encode a cursor (createdAt timestamp) into an opaque token. */
function encodeCursor(createdAt: number): string {
	return Buffer.from(`c:${createdAt}`).toString('base64url');
}

/** Decode a cursor token back to a createdAt timestamp. */
function decodeCursor(cursor: string): number | null {
	try {
		const decoded = Buffer.from(cursor, 'base64url').toString('utf8');
		const match = /^c:(-?\d+)$/.exec(decoded);
		return match ? Number(match[1]) : null;
	} catch {
		return null;
	}
}

function createD1Store(d1: D1Database): BoardStore {
	// Initialize schema on first use
	let schemaInitialized = false;

	async function ensureSchema(): Promise<void> {
		if (schemaInitialized) return;
		schemaInitialized = true;
		const stmt = d1.prepare(`
			CREATE TABLE IF NOT EXISTS board_messages (
				id TEXT PRIMARY KEY,
				text TEXT NOT NULL,
				image TEXT,
				hue INTEGER NOT NULL,
				status TEXT NOT NULL DEFAULT 'visible',
				created_at INTEGER NOT NULL
			)
		`);
		try {
			await stmt.run();
		} catch (e) {
			console.error('[bnji] board d1 schema init failed:', e);
		}
	}

	return {
		kind: 'd1',
		async listMessages({ limit, cursor }) {
			await ensureSchema();

			const args: unknown[] = [];
			let query = `
				SELECT id, text, image, hue, status, created_at as createdAt
				FROM board_messages
				WHERE status = 'visible'
			`;

			if (cursor) {
				const decoded = decodeCursor(cursor);
				if (decoded !== null) {
					query += ` AND created_at <= ?`;
					args.push(decoded);
				}
			}

			query += ` ORDER BY created_at DESC LIMIT ?`;
			args.push(limit);

			try {
				const stmt = d1.prepare(query);
				const stmtBound = args.length > 0 ? stmt.bind(...args) : stmt;
				const rows = (await stmtBound.all()) as Array<{
					id: string;
					text: string;
					image: string | null;
					hue: number;
					status: string;
					createdAt: number;
				}>;

				const messages: BoardMessage[] = rows.map((row) => ({
					id: row.id,
					text: row.text,
					image: row.image ?? undefined,
					hue: row.hue,
					status: row.status as MessageStatus,
					createdAt: row.createdAt,
				}));

				const nextCursor =
					messages.length === limit && messages.length > 0
						? encodeCursor(messages[messages.length - 1].createdAt)
						: undefined;

				return { messages, nextCursor };
			} catch (error) {
				console.error('[bnji] board d1 list failed:', error);
				return { messages: [], nextCursor: undefined };
			}
		},
		async add(message) {
			await ensureSchema();
			try {
				await d1
					.prepare(`
						INSERT INTO board_messages (id, text, image, hue, status, created_at)
						VALUES (?, ?, ?, ?, ?, ?)
					`)
					.bind(
						message.id,
						message.text,
						message.image ?? null,
						message.hue,
						message.status,
						message.createdAt,
					)
					.run();
			} catch (error) {
				console.error('[bnji] board d1 add failed:', error);
				throw error;
			}
		},
		async updateStatus(id, status) {
			await ensureSchema();
			try {
				const result = await d1
					.prepare(`UPDATE board_messages SET status = ? WHERE id = ?`)
					.bind(status, id)
					.run();
				return result.success;
			} catch (error) {
				console.error('[bnji] board d1 updateStatus failed:', error);
				return false;
			}
		},
	};
}

/* --- kv provider ----------------------------------------------------------- */

type KvNamespace = {
	get(key: string): Promise<string | null>;
	put(key: string, value: string): Promise<void>;
	list(options?: { cursor?: string; limit?: number }): Promise<{
		keys: string[];
		list_complete: boolean;
		cursor: string;
	}>;
};

function createKvStore(kv: KvNamespace): BoardStore {
	// For KV, we'll store messages individually and use list() for pagination
	// The cursor will be the KV list cursor
	async function loadVisibleMessages(limit: number, cursor?: string): Promise<{
		messages: BoardMessage[];
		nextCursor?: string;
	}> {
		// In KV we store all messages; we need to scan through them
		// This is a simplified approach - a production implementation would use
		// a sorted index. For now, we'll load all and filter client-side.
		const results: BoardMessage[] = [];
		let currentCursor: string | undefined = cursor;

		while (results.length < limit) {
			const listResult = await kv.list({ cursor: currentCursor, limit: 100 });
			if (listResult.keys.length === 0) break;

			for (const key of listResult.keys) {
				if (key.startsWith('board:msg:')) {
					const raw = await kv.get(key);
					if (raw) {
						const msg = JSON.parse(raw) as BoardMessage;
						if (msg.status === 'visible') {
							results.push(msg);
						}
					}
				}
			}

			if (listResult.list_complete) {
				break;
			}
			currentCursor = listResult.cursor;
		}

		// Sort newest first
		results.sort((a, b) => b.createdAt - a.createdAt);
		const messages = results.slice(0, limit);
		const nextCursor = messages.length === limit && messages.length > 0
			? encodeCursor(messages[messages.length - 1].createdAt)
			: undefined;

		return { messages, nextCursor };
	}

	return {
		kind: 'kv',
		async listMessages({ limit, cursor }) {
			try {
				return await loadVisibleMessages(limit, cursor);
			} catch (error) {
				console.error('[bnji] board kv list failed:', error);
				return { messages: [], nextCursor: undefined };
			}
		},
		async add(message) {
			try {
				await kv.put(`board:msg:${message.id}`, JSON.stringify(message));
			} catch (error) {
				console.error('[bnji] board kv add failed:', error);
				throw error;
			}
		},
		async updateStatus(id, status) {
			try {
				const raw = await kv.get(`board:msg:${id}`);
				if (!raw) return false;
				const msg = JSON.parse(raw) as BoardMessage;
				msg.status = status;
				await kv.put(`board:msg:${id}`, JSON.stringify(msg));
				return true;
			} catch (error) {
				console.error('[bnji] board kv updateStatus failed:', error);
				return false;
			}
		},
	};
}

/* --- rest provider ---------------------------------------------------------- */

function createRestStore(url: string, token?: string): BoardStore {
	const headers = (): Record<string, string> => ({
		'content-type': 'application/json',
		...(token ? { authorization: `Bearer ${token}` } : {}),
	});
	return {
		kind: 'rest',
		async listMessages({ limit, cursor }) {
			const params = new URLSearchParams({ limit: String(limit) });
			if (cursor) params.set('cursor', cursor);
			const response = await fetch(`${url}?${params}`, { headers: headers() });
			if (!response.ok) throw new Error(`board rest list failed: ${response.status}`);
			const data = (await response.json()) as ListMessagesResult;
			return data;
		},
		async add(message) {
			const response = await fetch(url, {
				method: 'POST',
				headers: headers(),
				body: JSON.stringify(message),
			});
			if (!response.ok) throw new Error(`board rest add failed: ${response.status}`);
		},
		async updateStatus(id, status) {
			const response = await fetch(`${url}/${id}/status`, {
				method: 'PATCH',
				headers: headers(),
				body: JSON.stringify({ status }),
			});
			if (!response.ok) throw new Error(`board rest updateStatus failed: ${response.status}`);
			return true;
		},
	};
}

/* --- selection -------------------------------------------------------------- */

/**
 * Resolve the active store for one request. `env` is the Worker environment
 * (Astro.locals.runtime.env); bindings and secrets arrive there and nowhere
 * else. Falls back to memory when the configured provider is unavailable, so
 * the board UI always works.
 */
export function getBoardStore(env: Record<string, unknown> | undefined): BoardStore {
	const configured = BOARD_CONFIG.provider;

	// D1 is the preferred production provider
	if (configured === 'd1' || configured === 'memory') {
		const d1 = env?.BOARD_D1 as D1Database | undefined;
		if (d1 && typeof d1.prepare === 'function') return createD1Store(d1);
	}

	// KV as secondary persistent option
	if (configured === 'kv' || configured === 'memory') {
		const kv = env?.BOARD_KV as KvNamespace | undefined;
		if (kv && typeof kv.get === 'function') return createKvStore(kv);
	}

	if (configured === 'rest') {
		const url = env?.BOARD_REST_URL as string | undefined;
		if (url) return createRestStore(url, env?.BOARD_REST_TOKEN as string | undefined);
	}
	return memoryStore;
}

/**
 * BNJI.NET — shared rate limiter using KV with TTL.
 *
 * Uses Cloudflare KV to store rate-limit counters with a TTL, so two requests
 * hitting different Worker isolates are still throttled consistently. Each
 * (clientKey, window) pair writes to a KV key that expires after the window.
 *
 * The counter is a sliding window: each request checks the current count and
 * increments it. KV's atomic increment operation ensures safe concurrent access.
 *
 * No secrets, no credentials: keys are hashed client addresses only. The KV
 * namespace should be bound as RATE_LIMIT_KV in wrangler.json.
 *
 * Falls back to in-isolate memory limiting when KV is unavailable.
 */

type KvNamespace = {
	get(key: string): Promise<string | null>;
	put(key: string, value: string, options?: { expirationTtl?: number }): Promise<void>;
	// For atomic increments (CF Workers support this on KV)
	// @ts-expect-error - KV binding has more methods than our type declares
	increment?(key: string, amount?: number, options?: { expirationTtl?: number }): Promise<number>;
	delete(key: string): Promise<void>;
};

type Bucket = { stamps: number[] };

// In-isolate fallback
const memoryBuckets = new Map<string, Bucket>();
const MAX_KEYS = 2000;

/**
 * @param key      client identity (e.g. Astro.clientAddress)
 * @param windowMs sliding window size
 * @param maxHits  allowed hits inside the window
 * @returns true when the hit is allowed (and recorded)
 */
export function rateLimit(key: string, windowMs: number, maxHits: number): boolean {
	// If KV is available, use shared rate limiting
	const kv = getRateLimitKv();
	if (kv) {
		return rateLimitKv(kv, key, windowMs, maxHits);
	}
	// Fallback to in-isolate memory limiting
	return rateLimitMemory(key, windowMs, maxHits);
}

/**
 * Seconds until the rate limit window resets (for Retry-After header).
 */
export function retryAfterSeconds(key: string, windowMs: number): number {
	const kv = getRateLimitKv();
	if (kv) {
		return retryAfterSecondsKv(kv, key, windowMs);
	}
	const bucket = memoryBuckets.get(key);
	if (!bucket || bucket.stamps.length === 0) return 0;
	const oldest = bucket.stamps[0];
	return Math.max(1, Math.ceil((windowMs - (Date.now() - oldest)) / 1000));
}

// --- KV-based rate limiting ---

let cachedKv: KvNamespace | null = null;
let kvChecked = false;

function getRateLimitKv(): KvNamespace | null {
	if (kvChecked) return cachedKv;
	kvChecked = true;
	try {
		const mod = (eval('require') as (m: string) => unknown)('cloudflare:workers') as {
			env?: Record<string, unknown>;
		} | undefined;
		const env = mod?.env;
		if (env?.RATE_LIMIT_KV) {
			cachedKv = env.RATE_LIMIT_KV as KvNamespace;
			return cachedKv;
		}
	} catch {
		// KV not available
	}
	cachedKv = null;
	return null;
}

async function rateLimitKv(
	kv: KvNamespace,
	clientKey: string,
	windowMs: number,
	maxHits: number,
): boolean {
	const key = `rl:${clientKey}:${windowMs}`;
	const windowSec = Math.ceil(windowMs / 1000);

	try {
		// Try atomic increment first (best case)
		if (kv.increment) {
			const newValue = await kv.increment(key, 1, { expirationTtl: windowSec });
			if (newValue <= maxHits) return true;
			// Over the limit
			await kv.delete(key);
			return false;
		}
	} catch {
		// Fall back to get/put if increment isn't supported
	}

	try {
		const raw = await kv.get(key);
		const count = raw ? parseInt(raw, 10) : 0;
		if (count >= maxHits) return false;

		await kv.put(key, String(count + 1), { expirationTtl: windowSec });
		return true;
	} catch (e) {
		console.error('[bnji] rate limit kv failed, falling back to memory:', e);
		return rateLimitMemory(clientKey, windowMs, maxHits);
	}
}

async function retryAfterSecondsKv(
	kv: KvNamespace,
	clientKey: string,
	windowMs: number,
): number {
	const key = `rl:${clientKey}:${windowMs}`;
	const windowSec = Math.ceil(windowMs / 1000);
	try {
		const raw = await kv.get(key);
		const count = raw ? parseInt(raw, 10) : 0;
		// Estimate based on time elapsed in the window
		return Math.max(1, windowSec);
	} catch {
		return Math.max(1, Math.ceil(windowMs / 1000));
	}
}

// --- Memory-based fallback rate limiting ---

function rateLimitMemory(key: string, windowMs: number, maxHits: number): boolean {
	const now = Date.now();
	let bucket = memoryBuckets.get(key);
	if (!bucket) {
		if (memoryBuckets.size > MAX_KEYS) {
			// Prune stale keys instead of unbounded growth.
			for (const [k, b] of memoryBuckets) {
				if (b.stamps.length === 0 || now - b.stamps[b.stamps.length - 1] > windowMs) {
					memoryBuckets.delete(k);
				}
			}
		}
		bucket = { stamps: [] };
		memoryBuckets.set(key, bucket);
	}
	bucket.stamps = bucket.stamps.filter((t) => now - t < windowMs);
	if (bucket.stamps.length >= maxHits) return false;
	bucket.stamps.push(now);
	return true;
}

/**
 * BNJI.NET — public message board API boundary.
 *
 *   GET  /api/board                     newest-first visible messages (paginated)
 *        /api/board?limit=N              up to N messages (clamped to pageSize)
 *        /api/board?cursor=CURSOR        cursor-based pagination: returns the
 *                                       next page of older messages + a new cursor
 *   POST /api/board                     { text, image? } -> 201 { message }
 *
 * Cursor-based pagination: pass the nextCursor from one response to get the
 * next page. When nextCursor is absent, there are no more pages.
 *
 * This endpoint is NOT prerendered: it runs in the Worker on every request so
 * it can read environment bindings (storage) and enforce rate limits.
 *
 * Safety contract for user-generated content:
 *   - text: trimmed, control characters stripped, hard length cap; rendered
 *     client-side via textContent only (never innerHTML);
 *   - image: accepted ONLY as a data: URL of an allowed MIME type under the
 *     size cap; re-validated here (never trust the client); stored as-is and
 *     rendered in an <img> with no scripting surface;
 *   - rate limit: shared KV-based counter so different Worker isolates still
 *     throttle consistently; one post per cooldown per client address, plus
 *     an hourly cap;
 *   - moderation: hidden/deleted/reported messages never reach GET; status
 *     field exists for future moderation UI (schema + enforcement only);
 *   - no credentials ever flow to the client; storage secrets live in env.
 */
import { BOARD_CONFIG } from '../../config/board.config';
import { getBoardStore, type BoardMessage, type MessageStatus } from '../../server/board-store';
import { rateLimit, retryAfterSeconds } from '../../server/ratelimit';
import { serverEnvironment } from '../../server/env';
import type { APIContext } from 'astro';

export const prerender = false;

const CONTROL_CHARS = /[\u0000-\u0008\u000b-\u001f\u007f]/g;

function clientKey(request: Request): string {
	const cf = (request as Request & { cf?: { connectingIp?: string } }).cf;
	return cf?.connectingIp ?? request.headers.get('cf-connecting-ip') ?? 'unknown';
}

function json(data: unknown, status = 200): Response {
	return new Response(JSON.stringify(data), {
		status,
		headers: {
			'content-type': 'application/json',
			// Board data is never cached by the edge: visitors must see fresh
			// messages, and POST responses must not be replayed.
			'cache-control': 'no-store',
		},
	});
}

/** Re-validate an attached image data URL. Returns the URL or undefined. */
function sanitizeImage(value: unknown): string | undefined {
	if (typeof value !== 'string' || value.length === 0) return undefined;
	const match = /^data:(image\/(?:png|jpeg|webp|gif));base64,([A-Za-z0-9+/=]+)$/.exec(value);
	if (!match) return undefined;
	if (!BOARD_CONFIG.allowedImageTypes.includes(match[1])) return undefined;
	// base64 length -> bytes (3/4 ratio), must fit the configured cap.
	const bytes = Math.floor((match[2].length * 3) / 4);
	if (bytes > BOARD_CONFIG.maxImageBytes) return undefined;
	return value;
}

/**
 * Validate a status value for the message board.
 */
function isValidStatus(status: unknown): status is MessageStatus {
	return (
		typeof status === 'string' &&
		['visible', 'hidden', 'reported', 'deleted'].includes(status)
	);
}

export async function GET(context: APIContext): Promise<Response> {
	const env = await serverEnvironment();
	const store = getBoardStore(env);

	// Parse limit from query params, defaulting to BOARD_CONFIG.defaultVisible
	const requestedLimit = Number(context.url.searchParams.get('limit') ?? BOARD_CONFIG.defaultVisible);
	const limit = Math.min(
		Math.max(1, Number.isFinite(requestedLimit) ? requestedLimit : BOARD_CONFIG.defaultVisible),
		BOARD_CONFIG.pageSize,
	);

	// Parse cursor for pagination
	const cursor = context.url.searchParams.get('cursor') ?? undefined;

	try {
		const { messages, nextCursor } = await store.listMessages({ limit, cursor });
		return json({
			messages,
			provider: store.kind,
			limit,
			...(nextCursor ? { nextCursor } : {}),
		});
	} catch (error) {
		console.error('[bnji] board list failed:', error);
		return json({ error: 'storage_unavailable', messages: [] }, 503);
	}
}

export async function POST(context: APIContext): Promise<Response> {
	const env = await serverEnvironment();
	const store = getBoardStore(env);
	const key = clientKey(context.request);

	// Abuse protection: cooldown + hourly cap, per client address.
	// Uses shared KV-based rate limiting so different Worker isolates
	// are throttled consistently.
	if (!rateLimit(`board:post:${key}`, BOARD_CONFIG.postCooldownSeconds * 1000, 1)) {
		return json(
			{
				error: 'rate_limited',
				retryAfter: retryAfterSeconds(`board:post:${key}`, BOARD_CONFIG.postCooldownSeconds * 1000),
			},
			429,
		);
	}
	if (!rateLimit(`board:hour:${key}`, 3_600_000, 20)) {
		return json({ error: 'rate_limited', retryAfter: 60 }, 429);
	}

	let payload: unknown;
	try {
		payload = await context.request.json();
	} catch {
		return json({ error: 'invalid_json' }, 400);
	}

	const body = (payload ?? {}) as { text?: unknown; image?: unknown; status?: unknown };

	// Enforce 250-character limit server-side (reject, don't truncate)
	const text = typeof body.text === 'string' ? body.text.replace(CONTROL_CHARS, '').trim() : '';

	if (text.length === 0) {
		return json({ error: 'empty_text' }, 422);
	}

	if (text.length > BOARD_CONFIG.maxTextLength) {
		return json(
			{
				error: 'text_too_long',
				maxLength: BOARD_CONFIG.maxTextLength,
				actualLength: text.length,
			},
			400,
		);
	}

	const image = sanitizeImage(body.image);

	// Validate status if provided (for future moderation operations)
	// Default to 'visible' for new public messages
	const status: MessageStatus = body.status && isValidStatus(body.status) ? body.status : 'visible';

	const message: BoardMessage = {
		id: `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
		text,
		...(image ? { image } : {}),
		// Stable tint seed, derived once so every visitor sees the same hue.
		hue: Math.floor(Math.random() * 360),
		status,
		createdAt: Date.now(),
	};

	try {
		await store.add(message);
		return json({ message, provider: store.kind }, 201);
	} catch (error) {
		console.error('[bnji] board add failed:', error);
		return json({ error: 'storage_unavailable' }, 503);
	}
}
